INSERT INTO properties (id, owner_id, title, slug, type, short_description, long_description, address, city, postal_code, region, country, capacity, bedrooms, beds, bathrooms, price_per_night, cleaning_fee, eco_score, status, created_at, updated_at) VALUES
(1, 2, 'Cabane boisée avec bain nordique', 'cabane-dans-les-arbres-avec-spa', 'treehouse', 'Une cabane en bois chaleureuse avec terrasse et bain nordique, pensée pour une parenthèse nature proche de Pierrefonds.', 'Cette cabane boisée a été imaginée comme un refuge calme pour s''éloigner du rythme quotidien. Installée dans un environnement arboré, elle valorise les matières naturelles, la lumière douce et une relation directe avec la forêt, sans chercher le luxe excessif.\n\nLa terrasse devient le coeur de l''expérience : on s''y installe pour lire, prendre un petit-déjeuner fictif ou profiter du bain nordique dans une ambiance de week-end insolite. Le logement reste compact, mais son agencement privilégie le confort essentiel et une vraie sensation de cocon.\n\nCette adresse convient surtout à un séjour en couple, une pause bien-être ou une première expérience d''hébergement insolite. Elle illustre l''esprit AtypikHouse : simplicité, nature, déconnexion et tourisme responsable dans un cadre premium mais accessible.', 'Chemin des chênes', 'Pierrefonds', '60350', 'Hauts-de-France', 'France', 2, 1, 1, 1, 185.00, 35.00, 5, 'published', NOW(), NOW()),
(2, 2, 'Cabane cocooning en jardin nature', 'yourte-nature-en-foret', 'other', 'Un petit refuge en bois ouvert sur un jardin arboré, idéal pour un séjour simple, calme et dépaysant.', 'Ce logement cocooning prend la forme d''un refuge en bois à taille humaine, installé dans un cadre végétal et paisible. Son intérêt vient de son ambiance intime : une terrasse accueillante, des lignes arrondies et une présence forte du bois qui donnent immédiatement envie de ralentir.\n\nL''expérience proposée reste volontairement simple. On vient ici pour profiter d''un hébergement insolite sans perdre les repères du confort : un couchage chaleureux, un coin pratique pour un court séjour et un extérieur pensé pour respirer au calme. Le cadre convient bien à une escapade proche de la nature, sans décor artificiel ni promesse disproportionnée.\n\nCette cabane est adaptée à un couple ou à de petits voyageurs qui veulent tester une nuit différente, accessible et rassurante. Elle remplace l''idée de yourte dans le seed par un visuel plus cohérent avec la photo actuelle.', 'Route forestière', 'Compiègne', '60200', 'Hauts-de-France', 'France', 4, 1, 3, 1, 115.00, 20.00, 4, 'published', NOW(), NOW()),
(3, 2, 'Cabane flottante au bord de l’eau', 'cabane-flottante-sur-lac', 'floating_cabin', 'Une cabane sur l’eau avec ponton, parfaite pour un réveil calme face au lac.', 'Cette cabane flottante propose une immersion douce au bord de l''eau. Le logement est pensé comme une parenthèse silencieuse, où le ponton, la vue sur le lac et les reflets naturels deviennent les principaux éléments de décor.\n\nL''ambiance est volontairement apaisante : on y vient pour lire, observer la lumière changer sur l''eau, écouter les sons du lieu et profiter d''un séjour nature différent d''une location classique. La cabane conserve un confort simple, adapté à une ou deux nuits, avec l''essentiel pour se sentir installé sans transformer l''expérience en resort.\n\nCe type d''hébergement convient particulièrement à un couple ou à deux voyageurs qui cherchent un week-end insolite, calme et facile à comprendre. Il met en avant la promesse AtypikHouse : vivre un lieu atypique, mais crédible, accessible et responsable.', 'Lac des songes', 'Chantilly', '60500', 'Hauts-de-France', 'France', 2, 1, 1, 1, 160.00, 30.00, 4, 'published', NOW(), NOW()),
(4, 2, 'Tiny house écologique en bois', 'tiny-house-ecologique', 'tiny_house', 'Une micro-maison en bois lumineuse, bien agencée pour un séjour sobre et confortable.', 'Cette tiny house écologique met en avant une manière plus compacte et plus responsable de voyager. Son architecture en bois, sa terrasse et son volume optimisé créent un hébergement insolite facile à comprendre, rassurant et cohérent avec un séjour nature.\n\nL''intérieur est pensé pour aller à l''essentiel : un espace nuit confortable, une kitchenette fonctionnelle et des équipements simples qui permettent de profiter d''un court séjour sans superflu. Le charme vient justement de cette sobriété, avec une sensation de cabane contemporaine plutôt qu''une petite maison standard.\n\nCe logement s''adresse aux voyageurs qui veulent tester une expérience minimaliste mais agréable, en couple ou en petit groupe. Il convient à une pause au vert, à un week-end responsable ou à une première découverte de la tiny house, avec un bon équilibre entre confort, autonomie et déconnexion.', 'Rue des prairies', 'Senlis', '60300', 'Hauts-de-France', 'France', 3, 1, 2, 1, 98.00, 25.00, 5, 'published', NOW(), NOW()),
(5, 2, 'Dôme nature avec terrasse', 'dome-romantique-avec-vue', 'dome', 'Un dôme lumineux posé sur une terrasse bois, pour une nuit insolite en pleine nature.', 'Ce dôme nature propose une expérience de glamping douce, centrée sur la lumière, l''ouverture et la sensation d''être entouré de végétation. Sa forme géodésique apporte immédiatement un caractère insolite, tout en restant accueillante et lisible pour les voyageurs.\n\nLa terrasse prolonge le logement vers l''extérieur et permet d''imaginer un petit-déjeuner au calme, une soirée sous le ciel ou simplement un moment de repos au milieu du paysage. À l''intérieur, l''espace reste pensé pour le confort d''un court séjour, avec une ambiance chaleureuse et une vue qui participe à l''expérience.\n\nCe dôme convient bien à un week-end en couple, à une pause contemplative ou à une découverte du tourisme responsable sous une forme plus premium. Le positionnement reste réaliste : un cocon original, naturel et confortable, sans basculer dans le décor de luxe artificiel.', 'Colline verte', 'Annecy', '74000', 'Auvergne-Rhône-Alpes', 'France', 2, 1, 1, 1, 172.00, 35.00, 4, 'published', NOW(), NOW()),
(6, 2, 'Pod familial en bois avec terrasse', 'roulotte-familiale', 'other', 'Un hébergement familial compact en bois, avec terrasse et jardin pour une escapade douce à la campagne.', 'Ce pod familial en bois offre une alternative crédible à la roulotte traditionnelle : un petit volume arrondi, chaleureux et facile à vivre, installé dans un jardin calme. Le logement garde un esprit insolite tout en restant accessible aux familles qui veulent une expérience simple et rassurante.\n\nLa terrasse et le mobilier extérieur permettent de profiter du séjour dehors, de partager un repas fictif ou de laisser les enfants découvrir un cadre plus proche de la nature. L''ambiance générale évoque la campagne, les matières boisées et une pause sans complication.\n\nCe logement est adapté à un court séjour familial, à une étape nature ou à une première nuit dans un hébergement atypique. Il ne cherche pas à imiter une roulotte si la photo ne le montre pas : le titre et le contenu assument désormais un pod en bois cohérent avec le visuel.', 'Domaine des vergers', 'Tours', '37000', 'Centre-Val de Loire', 'France', 5, 2, 4, 1, 125.00, 30.00, 3, 'published', NOW(), NOW()),
(7, 2, 'Refuge forestier en bois', 'lodge-insolite-en-campagne', 'other', 'Un lodge sobre et chaleureux au cœur des arbres, pensé pour ralentir le temps d’un week-end.', 'Ce refuge forestier mise sur une architecture simple et une ambiance très nature. Le bois, la silhouette compacte et l''implantation au milieu des arbres donnent une impression de cabane contemporaine, plus sobre qu''un chalet classique et plus immersive qu''un hébergement standard.\n\nL''expérience repose sur la déconnexion : profiter du calme, marcher à proximité, cuisiner simplement et retrouver une relation plus directe avec l''extérieur. Le logement conserve un niveau de confort adapté à un séjour court, sans surcharge décorative ni promesse de luxe inaccessible.\n\nCe refuge convient aux couples, aux amis ou aux petites familles qui veulent un week-end insolite proche de Paris, dans un esprit responsable. Il s''intègre naturellement à l''univers AtypikHouse : un hébergement différent, fiable, chaleureux et crédible pour une démonstration de marketplace.', 'Chemin rural', 'Provins', '77160', 'Île-de-France', 'France', 4, 2, 3, 1, 145.00, 28.00, 4, 'published', NOW(), NOW()),
(8, 2, 'Maison perchée premium en forêt', 'maison-perchee-premium', 'treehouse', 'Une maison perchée lumineuse avec grande terrasse, pour une escapade nature plus haut de gamme.', 'Cette maison perchée premium est pensée comme le logement signature de la sélection. Installée dans un cadre forestier, elle associe la sensation d''être au-dessus du sol, une architecture vitrée et une terrasse généreuse qui valorise pleinement l''immersion dans les arbres.\n\nL''ambiance est plus haut de gamme que les autres hébergements, mais reste naturelle : bois apparent, lumière chaude, vue végétale et espaces pensés pour se poser. On imagine facilement une soirée calme, un moment de lecture ou un week-end à plusieurs dans un cadre qui change réellement du quotidien.\n\nCe logement convient à un séjour en couple, entre amis proches ou en petite famille. Il met en avant le positionnement premium accessible d''AtypikHouse : une expérience forte, visuelle et rassurante, sans transaction réelle dans le cadre de ce projet étudiant fictif.', 'Bois des brumes', 'Fontainebleau', '77300', 'Île-de-France', 'France', 4, 2, 2, 1, 220.00, 45.00, 5, 'published', NOW(), NOW()),
(9, 2, 'Cabane flottante sur l’étang', 'cabane-flottante-sur-etang', 'floating_cabin', 'Une cabane en bois posée sur l’eau, idéale pour vivre un séjour insolite entre calme, nature et réveil face à l’étang.', 'Cette cabane flottante offre une expérience rare : dormir au plus près de l’eau, dans un logement chaleureux pensé pour la détente. Sa grande terrasse permet de profiter du calme de l’étang, de lire au soleil ou simplement d’observer les reflets de la nature tout au long de la journée.\n\nL’intérieur, lumineux grâce aux larges baies vitrées, propose un confort simple et agréable pour un court séjour en couple, en famille ou entre amis. Le bois, les ouvertures sur l’extérieur et l’environnement aquatique créent une atmosphère apaisante, parfaite pour déconnecter.\n\nCe logement correspond pleinement à l’esprit AtypikHouse : un hébergement insolite, confortable, dépaysant et intégré dans un cadre naturel. Il convient particulièrement aux voyageurs qui recherchent une parenthèse calme sans partir loin de la région.', 'Étang des roseaux', 'Pierrefonds', '60350', 'Hauts-de-France', 'France', 4, 2, 2, 1, 185.00, 35.00, 5, 'published', NOW(), NOW()),
(10, 2, 'Dôme vitré au milieu des vergers', 'dome-vitre-vergers', 'dome', 'Un dôme lumineux installé au cœur d’un verger, parfait pour une nuit insolite sous le ciel provençal.', 'Ce dôme vitré invite à vivre une expérience douce et dépaysante au cœur d’un environnement naturel ouvert. Installé sur une terrasse en bois, il permet de profiter pleinement de la lumière, du paysage et de l’ambiance paisible des vergers environnants.\n\nÀ l’intérieur, l’espace est pensé pour un séjour à deux, avec une atmosphère simple, intime et confortable. Les ouvertures vitrées créent une vraie connexion avec l’extérieur, tout en conservant l’esprit cocooning d’un hébergement insolite.\n\nCe logement est idéal pour une escapade romantique, une pause au calme ou une première expérience de glamping. Le cadre naturel, la terrasse et la vue dégagée en font une adresse fictive parfaitement adaptée à l’univers AtypikHouse : nature, originalité, simplicité et évasion.', 'Chemin des amandiers', 'Forcalquier', '04300', 'Provence-Alpes-Côte d’Azur', 'France', 2, 1, 1, 1, 155.00, 30.00, 4, 'published', NOW(), NOW()),
(11, 2, 'Kota familial en pleine campagne', 'kota-familial-campagne', 'other', 'Un kota en bois chaleureux, entouré de haies et de champs, pensé pour un séjour nature en famille ou entre amis.', 'Ce kota familial propose une expérience authentique dans un cadre rural calme et verdoyant. Avec sa structure en bois et sa terrasse extérieure, il offre une atmosphère chaleureuse, idéale pour prendre le temps de se retrouver loin du quotidien.\n\nLe logement est adapté aux courts séjours en famille ou entre amis. Son environnement ouvert, bordé de haies et de champs, donne une vraie sensation de tranquillité. La terrasse permet de profiter des repas en extérieur ou de moments de repos au calme.\n\nL’esprit du lieu repose sur la simplicité, le confort essentiel et le contact avec la nature. C’est une fiche cohérente pour un hébergement insolite accessible, sans luxe excessif, mais avec un vrai charme. Le kota s’intègre bien dans l’univers AtypikHouse grâce à son côté atypique, familial et dépaysant.', 'Route des haies', 'Amiens', '80000', 'Hauts-de-France', 'France', 4, 2, 3, 1, 130.00, 30.00, 4, 'published', NOW(), NOW()),
(12, 2, 'Lodge en bois avec bain nordique', 'lodge-bois-bain-nordique', 'other', 'Un lodge en bois avec terrasse et bain nordique, parfait pour une parenthèse détente au cœur d’un environnement naturel.', 'Ce lodge en bois est pensé pour les voyageurs qui recherchent un séjour nature avec une vraie dimension détente. Sa terrasse, son environnement arboré et son bain nordique créent une atmosphère chaleureuse, idéale pour un week-end en couple, entre amis ou en petite famille.\n\nL’hébergement associe le charme du bois à un confort moderne. Les espaces extérieurs permettent de profiter du calme, tandis que le bain nordique apporte une expérience bien-être très appréciée après une journée de balade ou de découverte de la région.\n\nCe logement correspond à un positionnement plus premium tout en restant cohérent avec l’esprit AtypikHouse : un lieu insolite, confortable, ancré dans la nature et pensé pour la déconnexion. Il peut être mis en avant comme logement coup de cœur ou séjour détente.', 'Sentier des sapins', 'Gérardmer', '88400', 'Grand Est', 'France', 4, 2, 2, 1, 215.00, 40.00, 5, 'published', NOW(), NOW());
